while i < len(active):
    if active[i]:
        start = i
        while i < len(active) and active[i]:
            i += 1
        events.append((start, i-1))
    else:
        i += 1

event_list = []
for s, e in events:
    event_list.append({
        "onset": target_dates[s].isoformat(),
        "end": target_dates[e].isoformat()
    })

print(f"Events: {event_list}")

